// What web-vitals does under the hood, simplified, to show how each metric is computed.
// In production use the `web-vitals` library instead: it handles bfcache, prerender and visibility edge cases.

// LCP: the last candidate before the first input or page hide.
let lcp = 0;
new PerformanceObserver((list) => {
  const entries = list.getEntries();
  const last = entries[entries.length - 1] as PerformanceEntry & { renderTime: number; loadTime: number };
  lcp = last.renderTime || last.loadTime; // renderTime may be 0 for cross-origin images without Timing-Allow-Origin
}).observe({ type: 'largest-contentful-paint', buffered: true });

// CLS: largest session window (gap < 1 s, window <= 5 s), ignoring shifts right after input.
type Shift = PerformanceEntry & { value: number; hadRecentInput: boolean };
let cls = 0;
let windowValue = 0;
let windowStart = 0;
let lastShift = 0;
new PerformanceObserver((list) => {
  for (const e of list.getEntries() as Shift[]) {
    if (e.hadRecentInput) continue;
    const startsNewWindow = e.startTime - lastShift > 1000 || e.startTime - windowStart > 5000;
    if (startsNewWindow) {
      windowValue = 0;
      windowStart = e.startTime;
    }
    windowValue += e.value;
    lastShift = e.startTime;
    cls = Math.max(cls, windowValue);
  }
}).observe({ type: 'layout-shift', buffered: true });

// INP: longest duration per interactionId; worst interaction, ignoring one outlier per 50.
type EventEntry = PerformanceEntry & { interactionId: number; duration: number };
const byInteraction = new Map<number, number>();
new PerformanceObserver((list) => {
  for (const e of list.getEntries() as EventEntry[]) {
    if (!e.interactionId) continue; // hover, scroll and non-interaction events have no id
    byInteraction.set(e.interactionId, Math.max(byInteraction.get(e.interactionId) ?? 0, e.duration));
  }
}).observe({ type: 'event', buffered: true, durationThreshold: 16 } as PerformanceObserverInit);

function currentInp(): number {
  const sorted = [...byInteraction.values()].sort((a, b) => b - a);
  const skip = Math.min(Math.floor(sorted.length / 50), sorted.length - 1);
  return sorted.length ? sorted[skip] : 0;
}

addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'hidden') {
    const body = JSON.stringify({ lcp, cls, inp: currentInp(), route: location.pathname });
    navigator.sendBeacon('/rum', body);
  }
});

// Loading patterns in code: interaction-driven import, idle prefetch, and prerender-aware analytics.

// 1. Load a heavy widget only when the user asks for it, and warm it up on hover.
let editorModule: Promise<typeof import('./rich-editor')> | null = null;
const loadEditor = () => (editorModule ??= import('./rich-editor'));

export function wireEditorButton(button: HTMLButtonElement, mount: HTMLElement): void {
  button.addEventListener('pointerenter', () => void loadEditor(), { once: true }); // prefetch on intent
  button.addEventListener('click', async () => {
    button.disabled = true;
    const { createEditor } = await loadEditor();
    createEditor(mount);
  });
}

// 2. Prefetch the next route's chunk when the browser is idle and the network is not constrained.
type NetInfo = { saveData?: boolean; effectiveType?: string };
export function prefetchWhenIdle(load: () => Promise<unknown>): void {
  const conn = (navigator as Navigator & { connection?: NetInfo }).connection;
  if (conn?.saveData || conn?.effectiveType === '2g') return; // respect constrained users
  const run = () => void load().catch(() => {});
  if ('requestIdleCallback' in window) requestIdleCallback(run, { timeout: 3000 });
  else setTimeout(run, 2000);
}

// 3. Speculation rules: prerender same-origin links on hover (Chromium), injected from script.
export function addSpeculationRules(): void {
  if (!HTMLScriptElement.supports?.('speculationrules')) return;
  const script = document.createElement('script');
  script.type = 'speculationrules';
  script.textContent = JSON.stringify({
    prerender: [
      {
        where: { and: [{ href_matches: '/*' }, { not: { href_matches: '/logout' } }, { not: { href_matches: '/cart/*' } }] },
        eagerness: 'moderate', // starts on hover or pointer down
      },
    ],
  });
  document.head.append(script);
}

// 4. Do not count a page view until a prerendered page is actually shown.
export function onPageShown(report: () => void): void {
  const doc = document as Document & { prerendering?: boolean };
  if (doc.prerendering) {
    document.addEventListener('prerenderingchange', report, { once: true });
  } else {
    report();
  }
}

// Yielding helpers and LoAF-based field attribution.

type SchedulerLike = {
  yield?: () => Promise<void>;
  postTask?: (cb: () => void, opts?: { priority?: 'user-blocking' | 'user-visible' | 'background' }) => Promise<void>;
};
const scheduler = (globalThis as { scheduler?: SchedulerLike }).scheduler;

export function yieldToMain(): Promise<void> {
  if (scheduler?.yield) return scheduler.yield(); // continue at the front of the queue
  return new Promise((resolve) => setTimeout(resolve, 0));
}

export function runInBackground(cb: () => void): void {
  if (scheduler?.postTask) void scheduler.postTask(cb, { priority: 'background' });
  else setTimeout(cb, 0);
}

// Process a large array without creating long tasks: yield after each time budget.
export async function forEachChunked<T>(items: readonly T[], fn: (item: T, i: number) => void, budgetMs = 8): Promise<void> {
  let sliceStart = performance.now();
  for (let i = 0; i < items.length; i++) {
    fn(items[i], i);
    if (performance.now() - sliceStart > budgetMs) {
      await yieldToMain();
      sliceStart = performance.now();
    }
  }
}

// Field attribution: which scripts cause slow frames (Chromium Long Animation Frames API).
type LoafScript = { sourceURL: string; sourceFunctionName: string; invoker: string; duration: number };
type LoafEntry = PerformanceEntry & { blockingDuration: number; scripts: LoafScript[] };

export function observeSlowFrames(report: (data: object) => void): void {
  if (!PerformanceObserver.supportedEntryTypes?.includes('long-animation-frame')) return;
  new PerformanceObserver((list) => {
    for (const entry of list.getEntries() as LoafEntry[]) {
      if (entry.blockingDuration < 100) continue; // only report the bad ones to limit volume
      const worst = [...entry.scripts].sort((a, b) => b.duration - a.duration)[0];
      report({
        duration: Math.round(entry.duration),
        blocking: Math.round(entry.blockingDuration),
        script: worst ? new URL(worst.sourceURL || location.href).pathname : 'unknown', // no query strings
        fn: worst?.sourceFunctionName,
        invoker: worst?.invoker, // e.g. "BUTTON#save.onclick" or "TimerHandler:setTimeout"
      });
    }
  }).observe({ type: 'long-animation-frame', buffered: true });
}

// A minimal fixed-height virtual list, plus leak-free subscriptions in an effect.
'use client';
import { useEffect, useRef, useState } from 'react';

type Props<T> = { items: T[]; rowHeight: number; height: number; overscan?: number; render: (item: T, index: number) => React.ReactNode };

export function VirtualList<T>({ items, rowHeight, height, overscan = 5, render }: Props<T>) {
  const [scrollTop, setScrollTop] = useState(0);
  const first = Math.max(0, Math.floor(scrollTop / rowHeight) - overscan);
  const visibleCount = Math.ceil(height / rowHeight) + overscan * 2;
  const last = Math.min(items.length, first + visibleCount);

  return (
    <div
      role="list"
      style={{ height, overflowY: 'auto', position: 'relative' }}
      onScroll={(e) => setScrollTop(e.currentTarget.scrollTop)}
    >
      <div style={{ height: items.length * rowHeight }} /> {/* spacer sets the scrollbar size */}
      {items.slice(first, last).map((item, i) => {
        const index = first + i;
        return (
          <div
            key={index} // acceptable only because rows hold no state; use item ids if they do
            role="listitem"
            aria-setsize={items.length}
            aria-posinset={index + 1}
            style={{ position: 'absolute', top: 0, left: 0, right: 0, height: rowHeight, transform: `translateY(${index * rowHeight}px)` }}
          >
            {render(item, index)}
          </div>
        );
      })}
    </div>
  );
}

// Every subscription is torn down by one AbortController; observers are disconnected.
export function useLiveChart(url: string) {
  const ref = useRef<HTMLCanvasElement>(null);
  useEffect(() => {
    const ac = new AbortController();
    const canvas = ref.current;
    if (!canvas) return;

    window.addEventListener('resize', () => draw(canvas), { signal: ac.signal, passive: true });
    const ro = new ResizeObserver(() => draw(canvas));
    ro.observe(canvas);
    const socket = new WebSocket(url);
    socket.addEventListener('message', (e) => push(JSON.parse(e.data as string)), { signal: ac.signal });
    const timer = setInterval(() => draw(canvas), 1000);

    return () => {
      ac.abort(); // removes both listeners
      ro.disconnect();
      socket.close();
      clearInterval(timer);
    };
  }, [url]);
  return ref;
}

const points: number[] = [];
function push(p: number) {
  points.push(p);
  if (points.length > 5000) points.splice(0, points.length - 5000); // bounded buffer, not an unbounded leak
}
function draw(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext('2d');
  if (!ctx) return;
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  points.forEach((p, i) => ctx.fillRect(i % canvas.width, canvas.height - p, 1, 1));
}
